import{_ as t,c as s,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"童溪易传","description":"童溪易传 - 童溪易传","frontmatter":{"title":"童溪易传","description":"童溪易传 - 童溪易传"},"headers":[],"relativePath":"zh/classics/tongxi/001.md","filePath":"zh/classics/tongxi/001.md"}'),r={name:"zh/classics/tongxi/001.md"};function o(i,a,c,p,d,u){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"童溪易传",tabindex:"-1"},[n("童溪易传 "),e("a",{class:"header-anchor",href:"#童溪易传","aria-label":"Permalink to “童溪易传”"},"​")],-1),e("p",null,"钦定四库全书经部一童溪易传易类提要",-1),e("p",null,"传字景孟，宁德人。淳熙八年进士，官韶州教授。董真卿以为临安人。朱彝尊经义考谓是书前有宁德林焞序，称与宗传「生同方，学同学，同及辛丑第」，则云临安人者误矣。宗传之说，大概祧梁、孟而宗王弼，故其书惟凭心悟，力斥象数之弊，至譬于误注本草之杀人。焞序述宗传之论，有",-1),e("p",null,"「性本无说，圣人本无言」之语，不免涉于异学，与杨简慈湖易传宗旨相同。盖弼易祖尚元虚，以阐发义理，汉学至是而始变。宋儒扫除古法，实从是萌芽。然胡、程祖其义理而归诸人事，故似浅近而醇实；宗传及简祖其元虚而索诸性天，故似高深而幻窅。考沈作哲作寓简，第一卷多谈易理，大抵以佛氏为宗。作哲为绍兴五年进士，其作寓简在淳熙元年，正与宗传同时。然则以禅言易，起于南宋之初，特作哲无成书，宗传及简则各有成编，显阐别经耳。春秋之书事，檀弓之说礼，必谨其变之所始。录存是编，俾学者知明万历以后，动以心学说易，流别于此。二人亦说周礼者，存俞庭椿、邱葵意也。乾隆四十五年十二月恭校上。",-1),e("p",null,"总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。易传原序：",-1),e("p",null,"「易」不可以「易」言也。盖自汉魏以来，世之言易者特多于他经，而其失也，比之言他经者亦多，此其故何也？易而言之之过也。夫人之情，有所难乎此也，则必有所畏谨乎此，而后获免轻议乎此之失。苟惟有所易也，则将争奇竞巧，而不知中庸之为至德；骋私任臆，而不知正直之为王道。如是则择焉不精，语焉不详，贸贸然不知朱紫苗莠之固有其辨，而吠声觇影之流始受其误矣。昔者夫子盖尝致谨乎此也，观其言曰：「加我数年，五十以学易，可以无大过矣。」夫学易而可以无易之过，此岂童心浅智者之所能为也？故圣如夫子，亦曰：「吾犹有待焉尔。」圣人之心，其不敢有所易如此也。而客有注易与本草孰先之问，为陶隐居者则告之曰：「易先。」其说曰：「注易误，不至杀人；本草误，人有不得其死者。」呜呼！自斯「人不至杀人」之言一发，而易之误自此始矣。世之轻议是经者，始纷纷矣。夫岂知本草误，误人命；注易误，误人心。人心一误，则形存性亡，为鬼蜮，为禽兽，将无所不至，其祸不亦惨于杀人矣乎？隐居之言曰：「本草误，人有不得其死者。」殊不知注易误，人有不得其生者，可谓智乎？或曰：「若之何而可以无易之过，如吾圣人之学易矣乎？」曰：「窃尝闻之，纲一举而目张，领一挈而裘顺，天下之有是物也，孰从而然欤？是故有所谓形而上者之制乎命，而后是物也得以肇其长短小大之形，吉凶消长之变。世之言易者，孰不曰舍是数不可以言易也，舍是象不可以言易也。而圣如夫子，亦必曰是数与象，易所不废也。然所以为是数与象者，或不知其说焉。则自一以往，而有不可胜计之数，自形色貌象以往，而有不可胜计之象，虽夫子亦末如之何矣。何也？圣人之于易，徒知据乎其会而已矣。据其会则凡憧憧于吾前者，莫吾眩也。圣人之于易也，徒知立乎其颠而已矣，立其颠则凡纷纷乎吾下者，莫吾度也。然则是数也，是象也，不知务其所以然之说也，而可乎？夫苟舍是而役役于不可胜计之地，此夫子所谓易之过也。然则舍数与象不可以为易，而其过也，乃数与象也，则金石草木所以为本草也，而其杀人也，乃金石草木也。天下同知本草误，误人命，而不知易误，误人心。吁，亦异哉！余不敏，一经之教，奉以周旋有日矣。」然学愈久而心愈杂，故虽疲神剔思于此，非不勤且至也，而未尝敢下轻议之笔。虽然，抑尝思之，加我之年，亦行甫及矣，进无用于时，退无补于身，不于此时也而有所勉焉，岂其志欤？若夫所谓大过，亦不敢自谓果可无也，愿就有道而正焉。王宗传谨述。",-1),e("p",null,"性本无说，圣人本无言，童溪之论性然也。易，尽性书也，而何至于多言？我知之矣。六丁敕易在天，三爻吞易在人。天而人之，易其显乎？余与童溪生同方，学同学，同及辛丑第，知其出处最详。公性能酒，饮已辄论易，尝曰：「吾远祖文中不善辨，为负苓者诎。使与我遇，当瞪目张胆灭其苓而饥之，曰：尔不有于人，又何有于身？」自是与人论易不倦，而于二系为详。出其门者十九青紫。既第之三年，教授曲江，越二年而书成，大书其影曰三十卷之易书，自谓无愧三圣，其笃于自信者欤？公姓王，讳宗传，字景孟，世谓天下王景孟，则其人也。开禧更元，族子𬳶客武陵，以书来曰：「刘君日新将以童溪易传膏馥天下后世，叔大夫父当序。」是以序。儒林郎、知衢州开化县主管劝农公事林焞炳叔序。",-1)])])}const f=t(r,[["render",o]]);export{_ as __pageData,f as default};
